import type { Category } from './types';

/*
 * Season overviews: one short narrative per season and section, shown on the
 * season pages and category pages in place of the individual stories.
 *
 * gam (2026-11-22): the season filters should read as an overview of the race
 * or storyline as a whole, not the per-player breakdowns of what the news said
 * about each player. The individual narratives stay as they are on team,
 * player and story pages, and each overview links to the ones it draws on.
 *
 * Each overview is written only from the narratives in its section (and their
 * sources), in the house style: what people expected at the time, then what
 * happened. Key: `<season start year>:<category>`, e.g. `2013:mvp-race` is the
 * 2013-14 MVP race.
 */
export type OverviewKey = `${number}:${Category}`;

export const seasonOverviews: Record<OverviewKey, string> = {
  // ── 1950s-1980s ─────────────────────────────────────────────────
  '1945:contenders': `The Rochester Royals won the NBL in their first season, sweeping Sheboygan in the finals behind Bob Davies and Al Cervi.`,
  '1946:contenders': `In the league's first season, Eddie Gottlieb's Philadelphia Warriors finished second in the East and then beat the Chicago Stags 4-1 for the championship, with Joe Fulks leading the league in scoring and popularizing the jump shot.`,
  '1946:surprises': `Washington went 49-11, ten games better than anyone, and the playoff format sent the two division winners into one long series against each other. Chicago knocked the Capitols out 4-2, and Philadelphia, only second in the East, came through the runners-up bracket to win the first title.`,
  '1947:contenders': `Philadelphia, the defending champion, won the East and had home court in the Finals, and it lost them to a Baltimore team that had needed a tiebreaker just to finish second in the West.`,
  '1947:draft-drama': `The BAA's first draft was meant to end bidding wars with the NBL for college players, and it started badly: No. 1 pick Clifton McNeely went into high school coaching and fourth pick Walt Dropo chose baseball.`,
  '1947:surprises': `For the second straight year a runner-up won the title. Baltimore, 28-20, beat the defending champion Warriors 4-2, and that Bullets franchise is the only champion that no longer exists.`,
  '1948:contenders': `Rochester had the best record at 45-15, but George Mikan's Lakers, the NBL champions the year before, swept the Royals and beat Red Auerbach's Capitols in six, the start of the league's first dynasty.`,
  '1948:draft-drama': `The 1948 draft was planned as a joint draft with the NBL until four NBL teams, including Minneapolis and Rochester, jumped to the BAA the day before and the deal collapsed. Providence took Andy Tonkovich first, and the Knicks' fourth pick, Dolph Schayes, had the best career.`,
  '1948:surprises': `Minneapolis and Rochester had just arrived from the rival NBL, and in their first BAA season they finished with the league's two best records. The Lakers then won the BAA's last title.`,
  '1949:contenders': `Syracuse had the new NBA's best record, 51-13, and home court in the Finals. Minneapolis won Game 1 on a Bob Harrison buzzer-beater, and George Mikan, the league's top scorer, carried the Lakers to the title in six.`,
  '1949:draft-drama': `Three Kentucky stars taken in the first round, Alex Groza, Wah Wah Jones and Ralph Beard, ignored the teams that drafted them and formed the new Indianapolis Olympians. St. Louis's territorial pick, Ed Macauley, had the best career in the class.`,
  '1949:surprises': `Rochester tied Minneapolis for the Central Division's best record at 51-17, lost a one-game tiebreaker for first, and was then swept in the first round by 40-28 Fort Wayne.`,
  '1950:contenders': `Minneapolis had won two straight titles, and Rochester knocked the Lakers out in the division finals. In New York, Ned Irish's Knicks were still trying to sell pro basketball in a city that belonged to baseball and hockey, on a payroll of about $100,000, and a 36-30 team made it all the way to the Finals. The Royals won the first three games, the Knicks the next three, and Rochester won Game 7 by four for the franchise's only title.`,
  '1950:draft-drama': `Boston passed on Bob Cousy to take Chuck Share first overall; Cousy went fourth to Tri-Cities, refused to report and ended up in Boston anyway, where he won six titles. Chuck Cooper and Earl Lloyd became the first Black players drafted.`,
  '1950:surprises': `Third-place New York beat Boston, which had home court, and reached its first Finals. Down 3-0 to Rochester, the Knicks became the first team to force a seventh game from 0-3, then lost it.`,
  '1951:contenders': `Rochester was the defending champion with the best record, but Minneapolis beat the Royals in the division finals and the Knicks in a seven-game Finals played mostly in secondary arenas, with the circus in Madison Square Garden.`,
  '1951:draft-drama': `The first pick, Bradley's Gene Melchiorre, never played in the NBA because of the college point-shaving scandal, and the class produced no Hall of Famers.`,
  '1951:surprises': `Every playoff team from the year before made it back, but the results changed: Minneapolis beat defending champion Rochester, and third-place New York beat Boston and East-leading Syracuse to return to the Finals.`,
  '1952:contenders': `For once the favorite simply won: the 48-22 Lakers had the best record and beat the Knicks 4-1 for a fifth title in six years, counting the 1948 NBL championship.`,
  '1952:draft-drama': `The NBA kept its draft order secret for fear of a rival amateur league. Milwaukee's No. 1 pick, Mark Workman, did little, and the Lakers' 10th pick, Clyde Lovellette, was the class's only All-Star and Hall of Famer in what is seen as one of the weakest drafts ever.`,
  '1952:surprises': `Philadelphia missed the playoffs and Baltimore got in at 16-54, still the worst record of any playoff team, before the Knicks swept them. Boston won its first playoff series, and Indianapolis played its last game.`,
  '1953:contenders': `George Mikan's Minneapolis Lakers, so dominant that the league had widened the lane to slow him down, won a third straight title and their fifth in six years.`,
  '1953:draft-drama': `Baltimore took Long Island University's Ray Felix and he was Rookie of the Year. Boston found two Hall of Famers from Kentucky, Frank Ramsey and Cliff Hagan.`,
  '1953:surprises': `With Indianapolis gone and only nine teams left, the league ran its playoffs as a round robin within each division, the only time it ever did. It was also the first season with a national TV contract.`,
  '1954:contenders': `In the first season with the 24-second shot clock, which Syracuse owner Danny Biasone had pushed for, Dolph Schayes's Nationals won the East and beat the Fort Wayne Pistons 4-3 in the Finals for the franchise's first title.`,
  '1954:draft-drama': `Baltimore took Furman's Frank Selvy first, and the Milwaukee Hawks took Bob Pettit second. Pettit was Rookie of the Year and then the league's first MVP.`,
  '1954:surprises': `Fort Wayne led Game 7 of the Finals 41-24 and lost 92-91 at Syracuse, the home team winning every game of the series. Teammate George Yardley later said he believed Andy Phillip, who lost the ball in the final seconds, had thrown it, and other Pistons were suspected of working with gamblers.`,
  '1955:contenders': `Paul Arizin led the 45-27 Philadelphia Warriors to the title, beating the Fort Wayne Pistons 4-1 in the Finals.`,
  '1955:draft-drama': `The Hawks took Dick Ricketts first and Rochester took Maurice Stokes second, and Stokes was the Hall of Famer. Philadelphia used a new rule to claim Overbrook High School senior Wilt Chamberlain as a territorial pick, years before he could play.`,
  '1955:mvp-race': `The league handed out its first MVP award, and it went to second-year star Bob Pettit, who led the NBA in both scoring (25.7) and rebounding (16.2) in the Hawks' first season in St. Louis.`,
  '1955:surprises': `The 37-35 Pistons fell behind St. Louis 0-2 in the division finals and won three straight, the first comeback from 0-2 in playoff history. In the round before, the Lakers had beaten the Hawks by 58 in George Mikan's last game.`,
  '1956:contenders': `In Bill Russell's rookie year Boston had the best record, 44-28, and St. Louis came out of a West where nobody finished above .500. The Hawks still took the Celtics to double overtime of Game 7 before Boston won its first title.`,
  '1956:draft-drama': `The big move of the 1956 draft happened before it: Red Auerbach sent Ed Macauley and the rights to Cliff Hagan to St. Louis for the pick Boston used on Bill Russell, the trade that built the Celtics dynasty.`,
  '1956:mvp-race': `Bob Pettit had the bigger numbers again, 24.7 points and 14.6 rebounds, but the players, who voted for the award then, chose Bob Cousy, who led the league in assists for the team with the best record. Pettit finished second.`,
  '1956:surprises': `St. Louis went 34-38, won its way out of a three-way tie and swept Minneapolis to reach the Finals with a losing record, then pushed Boston to double overtime of Game 7.`,
  '1957:contenders': `St. Louis had lost a seven-game Finals to Boston the year before. In the rematch the Hawks won in six, with Bob Pettit scoring a Finals-record 50 points in the 110-109 clincher. It is still the franchise's only title.`,
  '1957:draft-drama': `Cincinnati took Hot Rod Hundley first and traded him to Minneapolis. Boston found Sam Jones at No. 8, the best career in the class, and eighth-round pick Woody Sauldsberry was Rookie of the Year.`,
  '1957:mvp-race': `Dolph Schayes scored 24.9 a game and finished a close second, but the players voted Bill Russell MVP for the 49-23 Celtics. The writers put him only on the All-NBA second team, a split that kept happening.`,
  '1957:surprises': `In the Royals' first season in Cincinnati, Maurice Stokes suffered a major head injury in the last game of the season. He was later paralyzed and cared for by teammate Jack Twyman, and the league's teammate award is named for both.`,
  '1958:contenders': `This is where the Celtics' run begins. Built on Bill Russell's defense and Auerbach's fast break, Boston won every title from 1959 to 1966, a streak no team in a major American league has matched.`,
  '1958:draft-drama': `Last-place Minneapolis took Seattle University's Elgin Baylor first and he was Rookie of the Year. Syracuse found Hal Greer at No. 14, and Philadelphia's third-round pick, Frank Howard, chose baseball.`,
  '1958:mvp-race': `Bob Pettit led the league at a record 29.2 points for the 49-23 Hawks and won his second MVP easily, ahead of Bill Russell and rookie Elgin Baylor.`,
  '1958:surprises': `The defending champion Hawks went 49-23 and lost the division finals to a 33-39 Lakers team with rookie Elgin Baylor. Boston then swept Minneapolis, the first Finals sweep and the first Celtics-Lakers Finals.`,
  '1959:contenders': `The Celtics went 59-16, the best record by 10 games, beat rookie Wilt Chamberlain's Warriors in the East and then needed all seven games to beat the Hawks.`,
  '1959:draft-drama': `Wilt Chamberlain had played at Kansas, outside every team's territory, but the Warriors argued he was theirs because he grew up in Philadelphia, and the league agreed. He was MVP and Rookie of the Year in his first season.`,
  '1959:mvp-race': `Rookie Wilt Chamberlain averaged 37.6 points and 27.0 rebounds, led the league in both and won MVP, Rookie of the Year and All-Star MVP. Boston still beat his Warriors in the division finals.`,
  '1959:surprises': `In their last season in Minneapolis, the 25-50 Lakers swept the Pistons and took the Hawks to seven games in the division finals.`,
  '1960:contenders': `Boston, 57-22, met St. Louis in the Finals for the fourth time in five years and won 4-1 for a third straight title. It is still the Hawks' last Finals.`,
  '1960:draft-drama': `Cincinnati used its territorial pick on hometown star Oscar Robertson, also the first overall pick, and he averaged 30.5 points, 10.1 rebounds and 9.7 assists to win Rookie of the Year.`,
  '1960:mvp-race': `Elgin Baylor scored 34.8 a game and Bob Pettit had 27.9 points and 20.3 rebounds, but the players gave Bill Russell his second MVP for the 57-22 Celtics, while the writers again had him on the All-NBA second team.`,
  '1960:surprises': `In their first season in Los Angeles, the 36-43 Lakers beat Detroit and came within one game of the Finals, losing to the 51-28 Hawks in seven.`,
  '1961:contenders': `The Lakers, newly moved to Los Angeles, reached the Finals behind Elgin Baylor and Jerry West and lost to Boston, the first of seven Finals they would lose between 1962 and 1970.`,
  '1961:draft-drama': `The expansion Chicago Packers took Indiana's Walt Bellamy first and he averaged 31.6 points and 19.0 rebounds as a rookie. The 22nd pick, Doug Moe, never played in the NBA after his contract was voided over the point-shaving scandal.`,
  '1961:mvp-race': `Wilt Chamberlain averaged a record 50.4 points, including the 100-point game, and the players still voted for Bill Russell, because Boston became the first team to win 60. Russell won with almost twice Chamberlain's vote share, the clearest case of the argument that followed them: Chamberlain had the All-NBA first teams, Russell the MVPs from the players.`,
  '1961:surprises': `In Hershey, Pennsylvania, with no TV cameras present, Wilt Chamberlain scored 100 points against the Knicks, still the NBA single-game record.`,
  '1962:contenders': `Boston had the best record at 58-22, needed seven games against Oscar Robertson's Royals in the East, and beat the Lakers 4-2 for a fifth straight title in Bob Cousy's last season.`,
  '1962:draft-drama': `Chicago took Billy McGill first, but the class belonged to the territorial picks and Boston's ninth pick: Dave DeBusschere, Jerry Lucas and John Havlicek. Lucas went to the ABL, sat out when the team folded, and was Rookie of the Year in 1963-64.`,
  '1962:mvp-race': `Elgin Baylor averaged 34.0 points and finished second. Bill Russell, at 16.8 points and 23.6 rebounds for the 58-22 Celtics, won his fourth MVP and the All-Star Game MVP.`,
  '1962:surprises': `The 42-38 Royals knocked out the 48-32 Nationals with an overtime win in Syracuse, then took the Celtics to a seventh game in the division finals.`,
  '1963:contenders': `The first Finals between Bill Russell and Wilt Chamberlain wasn't close. The 59-21 Celtics, now without Cousy, beat Chamberlain's Warriors 4-1 for a sixth straight title.`,
  '1963:draft-drama': `New York took Duke's Art Heyman first. San Francisco took Nate Thurmond third, and he and Gus Johnson became the Hall of Famers of a class with fewer non-territorial picks reaching the NBA than any other.`,
  '1963:mvp-race': `Oscar Robertson won MVP at 31.4 points, 9.9 rebounds and a league-high 11.0 assists, with rookie Jerry Lucas helping the Royals to 55 wins, but Boston and Philadelphia still kept Cincinnati out of the Finals.`,
  '1963:surprises': `A year after going 31-49, the Warriors won the West with 48 wins under Alex Hannum, with rookie Nate Thurmond beside Wilt Chamberlain, and beat the Hawks in seven to reach the Finals.`,
  '1964:contenders': `Boston won a record 62 games. Philadelphia, with Wilt Chamberlain since January, took the Celtics to seven in the East before John Havlicek's steal ended it, and the Lakers lost Elgin Baylor to a knee injury and then the Finals 4-1.`,
  '1964:draft-drama': `The Knicks took Jim Barnes first and found Willis Reed with the 10th pick; Reed was Rookie of the Year and the 1970 MVP.`,
  '1964:mvp-race': `Oscar Robertson averaged 30.4 points and 11.5 assists, but Boston won a record 62 games and Bill Russell, at 14.1 points and 24.1 rebounds, won his fifth MVP with more than double Robertson's vote share.`,
  '1964:surprises': `A year after reaching the Finals, the sinking Warriors traded Wilt Chamberlain back to Philadelphia, to the 76ers, for three players and cash amid tension and money problems.`,
  '1965:contenders': `Philadelphia finished a game ahead of Boston, and the Celtics beat the 76ers 4-1 anyway. Red Auerbach had announced he was retiring, daring the league to take its "one last shot" at him, and after the Lakers won Game 1 of the Finals he named Bill Russell his successor, the NBA's first Black coach. Boston blew a 3-1 lead and held on in Game 7 for an eighth straight title.`,
  '1965:draft-drama': `San Francisco used the first pick on Fred Hetzel and its second first-rounder, fourth overall, on Rick Barry, who was Rookie of the Year and the best player in the class.`,
  '1965:mvp-race': `Wilt Chamberlain averaged 33.5 points and 24.6 rebounds and the 76ers edged Boston for the best record, so he won his second MVP over Jerry West. The Celtics then beat Philadelphia 4-1 in the playoffs.`,
  '1965:surprises': `Baltimore had the better record, but the injury-riddled Bullets were swept 3-0 by Richie Guerin's 36-44 Hawks.`,
  '1966:contenders': `Philadelphia had paired Wilt Chamberlain with Hal Greer and Chet Walker, and new coach Alex Hannum built a balanced offense around him. The 76ers went 68-13, the league's best record, and beat the Warriors in the Finals for the 76ers' first title.`,
  '1966:draft-drama': `In the first draft decided by a coin flip, the Knicks won it and took Cazzie Russell. Detroit's Dave Bing, the second pick, was Rookie of the Year and the Hall of Famer; Russell won a title in 1970 and made one All-Star team.`,
  '1966:mvp-race': `Under Alex Hannum, Wilt Chamberlain shot less and passed more, 24.1 points, 24.2 rebounds and 7.8 assists, for a 68-13 team, and won a third MVP by a wide margin over Nate Thurmond.`,
  '1966:surprises': `The expansion Bulls went 33-48 and made the playoffs in their first season, and the Knicks returned to the postseason for the first time since 1959.`,
  '1967:contenders': `Boston was only third in the league at 54-28 and getting old. Player-coach Bill Russell's Celtics came back from 3-1 down against the 76ers and beat the Lakers in six for their 10th title in 12 seasons.`,
  '1967:draft-drama': `Detroit won the coin flip and took Jimmy Walker. Baltimore's Earl Monroe, the second pick, was Rookie of the Year, and the Knicks' Walt Frazier, the fifth, had the best career; the two won the 1973 title together.`,
  '1967:mvp-race': `Wilt Chamberlain won a third straight MVP, his fourth, while leading the league in assists, far ahead of Lenny Wilkens. By July his feud with ownership had him traded to the Lakers, the first reigning MVP ever traded.`,
  '1967:surprises': `The defending champion 76ers won 62 games and led Boston 3-1 in the division finals, then lost three straight. That July they traded Wilt Chamberlain to the Lakers.`,
  '1968:contenders': `The aging Celtics were not the team of the early '60s, and Wilt Chamberlain's Lakers had home court in the Finals. Boston won Game 7 at the Forum anyway, 108-106, for Russell's 11th title in 13 seasons, and he retired after it.`,
  '1968:draft-drama': `San Diego won the coin flip and took Elvin Hayes. Baltimore took Wes Unseld second, and he won Rookie of the Year and MVP; the two won the 1978 title together in Washington.`,
  '1968:mvp-race': `Baltimore's Wes Unseld, the second pick, averaged 18.2 rebounds, second only to Wilt Chamberlain, and won both Rookie of the Year and MVP, turning the Bullets into a 57-win division winner in his first season.`,
  '1968:surprises': `Bill Russell's aging Celtics finished fourth in the East at 48-34. They upset Philadelphia and New York and then beat the Lakers in seven for their 11th title.`,
  '1969:contenders': `Red Holzman's defense-first Knicks had the league's best record but trailed the Lakers 3-2 in the Finals with Willis Reed hobbled. Reed's walk out for Game 7 and Walt Frazier's 36 points and 19 assists won New York its first title.`,
  '1969:draft-drama': `Expansion teams Milwaukee and Phoenix flipped a coin for the first pick and the right to take UCLA's Lew Alcindor. The Bucks won it, Phoenix took Neal Walk, and Alcindor made Milwaukee a 56-win team as a rookie.`,
  '1969:mvp-race': `Jerry West led the league at 31.2 points and rookie Lew Alcindor scored 28.8, but the players voted Willis Reed of the 60-22 Knicks MVP in a close race with West. Reed added All-Star and Finals MVP, the first player to win all three in one season.`,
  '1969:surprises': `After winning the 1969 title, Boston fell to 34-48 and missed the playoffs for the first time since 1951.`,
  '1970:contenders': `Milwaukee traded for an unhappy Oscar Robertson to play alongside Kareem Abdul-Jabbar. The Bucks went 66-16 with a 20-game winning streak and swept Baltimore in the Finals, winning the title in only the franchise's third year.`,
  '1970:draft-drama': `Detroit took Bob Lanier first, ahead of Rudy Tomjanovich and Pete Maravich. The pick that aged best came fourth: Boston's Dave Cowens shared Rookie of the Year and was MVP by 1973, in a class that sent six players to the Hall of Fame.`,
  '1970:mvp-race': `With Oscar Robertson beside him, Lew Alcindor led the Bucks to 66 wins, won his first scoring title at 31.7 points and took the MVP in a rout, far ahead of Jerry West.`,
  '1970:surprises': `The defending champion Knicks were expected to meet Milwaukee in the Finals, but the 42-40 Bullets beat them in seven. Baltimore had to open the Finals 48 hours later and was swept.`,
  '1971:contenders': `After years of Finals heartbreak and injuries, Wilt Chamberlain and Jerry West won the Lakers' first title in Los Angeles, with Chamberlain focused on defense and passing.`,
  '1971:draft-drama': `Cleveland took Notre Dame scorer Austin Carr first. Artis Gilmore, headed for the ABA, slid to 117th; he was ABA MVP as a rookie and turned out to be the best player in the class once the leagues merged in 1976.`,
  '1971:mvp-race': `The 69-13 Lakers split the vote between Jerry West and Wilt Chamberlain, who finished second and third. Kareem Abdul-Jabbar scored 34.8 points for the 63-win Bucks and became the first player to win MVP twice in his first three seasons.`,
  '1971:surprises': `Cowens, White and Havlicek's Celtics won 56 games and were the top seed, but New York beat them in five in the conference finals.`,
  '1972:contenders': `The 1970 Knicks, now with Jerry Lucas and Earl Monroe, won 57 games and met the Lakers in the Finals again. They lost Game 1 and won the next four for a second title in four years, the franchise's last for 53 years.`,
  '1972:draft-drama': `In the first draft open to underclassmen, Portland made Loyola's LaRue Martin the first pick. Buffalo took North Carolina junior Bob McAdoo second, and he became Rookie of the Year, a scoring champion and an MVP, while Julius Erving went 12th.`,
  '1972:mvp-race': `Tiny Archibald led the league in both scoring and assists for a losing Kings team, and Kareem Abdul-Jabbar scored 30.2 points, but the players chose Dave Cowens, the center of the 68-14 Celtics.`,
  '1972:surprises': `Five years after winning 68 games and a title, the 76ers went 9-73, still one of the worst records in NBA history.`,
  '1973:contenders': `The 59-win Bucks met Boston in the Finals. Down 3-2, Kareem Abdul-Jabbar's skyhook in double overtime won Game 6, but the Celtics won Game 7 in Milwaukee.`,
  '1973:draft-drama': `Philadelphia took Doug Collins first, and Buffalo's third pick, Ernie DiGregorio, was Rookie of the Year. George McGinnis, taken 22nd, became the only player in the class to make both an All-NBA team and an All-Star team.`,
  '1973:mvp-race': `Bob McAdoo won the scoring title at 30.6 points, but Kareem Abdul-Jabbar led the 59-23 Bucks to the league's best record and won a close vote for his third MVP in four years.`,
  '1973:surprises': `A year after going 21-61, Buffalo went 42-40 behind scoring champion Bob McAdoo and made the playoffs before losing to Boston in six.`,
  '1974:contenders': `Washington tied Boston for the best record at 60-22 and knocked the Celtics out, so the Bullets were heavy favorites in the Finals against the 48-34 Warriors. Golden State swept them, in the first title series with two Black head coaches.`,
  '1974:draft-drama': `Portland took UCLA's Bill Walton first, and he later brought the Blazers a title and an MVP. His teammate Jamaal Wilkes went 11th and was Rookie of the Year, and George Gervin, already in the ABA, lasted to 40th and had the best career.`,
  '1974:mvp-race': `Boston and Washington each won 60 games, but Buffalo's Bob McAdoo, at 34.5 points and 14.1 rebounds for a 49-win team, beat out Dave Cowens and Elvin Hayes for MVP.`,
  '1974:surprises': `Rick Barry's 48-34 Warriors were underdogs through the playoffs, then swept the 60-win Washington Bullets in the Finals.`,
  '1975:contenders': `The defending champion Warriors went 59-23 and were the West's top seed, but they lost to 42-40 Phoenix. Boston, which had fallen short as a 60-win team the year before, won 54 and beat the Suns in six for its 13th title.`,
  '1975:draft-drama': `Atlanta held the first and third picks and took David Thompson and Marvin Webster. Both signed with the ABA's Denver Nuggets instead, the only first-rounders that year to turn the NBA down.`,
  '1975:mvp-race': `In his first year as a Laker, Kareem Abdul-Jabbar led the league in rebounds but his team went 40-42 and missed the playoffs. He still edged Bob McAdoo and Dave Cowens in one of the closest votes yet, the only MVP whose team missed the postseason.`,
  '1975:surprises': `John MacLeod's Phoenix Suns went just 42-40, then beat Seattle and kept going to reach the franchise's first Finals.`,
  '1976:contenders': `Bill Walton, Maurice Lucas and new coach Jack Ramsay took a Portland team that had never made the playoffs to the title. Down 2-0 to the star-studded 76ers, the Blazers won four straight, and Walton was Finals MVP.`,
  '1976:draft-drama': `Houston took Maryland guard John Lucas first. Buffalo's sixth pick, Adrian Dantley, was Rookie of the Year, and Golden State's eighth pick, Robert Parish, had the longest and best career in a class with four Hall of Famers.`,
  '1976:mvp-race': `With a cast of little-known free agents, the Lakers were picked to finish near the bottom of their division. Instead they had the league's best record, 53-29, and Kareem Abdul-Jabbar won his fifth MVP by a wide margin, tying Bill Russell.`,
  '1976:surprises': `The Nets had just won the ABA's last championship, then sold Julius Erving to the 76ers for $3 million to secure their way into the NBA. Without him they went 22-60.`,
  '1977:contenders': `Washington, which had lost the Finals in 1971 and 1975, was only the East's third seed at 44-38. The Bullets beat Atlanta, San Antonio and Philadelphia, then won Game 7 of the Finals in Seattle, with Wes Unseld as Finals MVP. Portland had the league's best record at 58-24 with MVP Bill Walton, but his foot stress fracture in the playoffs ended the repeat.`,
  '1977:draft-drama': `Milwaukee took Indiana center Kent Benson first. Walter Davis, picked fifth by Phoenix, was Rookie of the Year, and Seattle's eighth pick, Jack Sikma, had the best career, with the 1979 title and seven straight All-Star picks.`,
  '1977:mvp-race': `Bill Walton won MVP for the league-best 58-24 Blazers despite missing games with foot trouble, and a stress fracture found in the playoffs ended Portland's hopes of a repeat.`,
  '1977:surprises': `A 44-38 Bullets team, the East's third seed, won the franchise's only championship, taking Game 7 of the Finals in Seattle.`,
  '1978:contenders': `Washington had the best record and home court in a rematch of the 1978 Finals it had won, but needed to come back from 3-1 down against San Antonio just to get there. Seattle won in five for its first title, with Dennis Johnson as Finals MVP.`,
  '1978:draft-drama': `Portland took Mychal Thompson first. Boston spent the sixth pick on Larry Bird, a junior who went back to Indiana State for his senior year, and waited. He arrived in 1979 and was Rookie of the Year and first-team All-NBA.`,
  '1978:mvp-race': `Moses Malone won MVP for Houston at 24.8 points and a league-leading 17.6 rebounds, with a record 587 offensive rebounds.`,
  '1978:surprises': `Kansas City jumped from 31 wins to 48, with Cotton Fitzsimmons named Coach of the Year and Phil Ford Rookie of the Year.`,
  '1979:contenders': `Magic Johnson and Larry Bird arrived in the same season and reshaped the league's title picture for a decade: Showtime in Los Angeles against the Celtics, three Finals meetings and eight titles between them, at a time when the NBA badly needed the boost. Magic won it right away: with Kareem Abdul-Jabbar hurt, the rookie played center in Game 6 and had 42 points to clinch the title.`,
  '1979:draft-drama': `The Lakers held the first pick only because New Orleans had to compensate them for signing Gail Goodrich. They took Michigan State sophomore Magic Johnson, the first underclassman picked first, and he won a title as a rookie.`,
  '1979:mvp-race': `Rookie Magic Johnson changed the Lakers, but the award went to Kareem Abdul-Jabbar, who won a record sixth MVP well ahead of Julius Erving in the last vote held by the players.`,
  '1979:surprises': `With rookie Larry Bird, Boston went from 29 wins to 61. Detroit went the other way, to 16-66, the worst record since the 9-73 76ers.`,
  '1980:contenders': `Boston and Philadelphia both went 62-20, and the Celtics beat the 76ers in seven in the conference finals. That left a 40-42 Houston team that Moses Malone had carried to the Finals, and Boston won in six.`,
  '1980:draft-drama': `Golden State traded Robert Parish and the No. 3 pick to Boston to get Joe Barry Carroll, a center it saw as having more upside. Boston took Kevin McHale with the pick, and Parish and McHale became pillars of its 1980s dynasty.`,
  '1980:mvp-race': `In the first MVP vote by the media rather than the players, Julius Erving narrowly beat second-year Larry Bird, whose Celtics tied Erving's 76ers for the best record.`,
  '1980:surprises': `Houston went 40-42 in the regular season, then Moses Malone carried the sixth-seeded Rockets all the way to the Finals, where Boston beat them in six. Kansas City, also 40-42, reached the conference finals too.`,
  '1981:contenders': `Pat Riley replaced the fired Paul Westhead early in the season, and his Showtime Lakers beat Philadelphia for the title, the first of four under Riley.`,
  '1981:draft-drama': `Isiah Thomas had just won an NCAA title and was reluctant to join Detroit, a 21-61 team. Jack McCloskey took him second anyway and built the Bad Boys around him.`,
  '1981:mvp-race': `Larry Bird's Celtics won 63 games, but Moses Malone's 31.1 points and 14.7 rebounds for a 46-36 Rockets team won him his second MVP, one of the few for a player whose team missed 50 wins.`,
  '1981:surprises': `The Celtics routed Philadelphia by 40 in Game 1 and came back from 3-1 down to force Game 7, as they had the year before. This time the 76ers won it in Boston Garden, and the crowd chanted "Beat LA!" for them.`,
  '1982:contenders': `Julius Erving's 76ers had lost the Finals to the Lakers twice in three years. They added reigning MVP Moses Malone from Houston, went 65-17 and swept Los Angeles for their first title since 1967.`,
  '1982:draft-drama': `Utah drafted Georgia's Dominique Wilkins third and traded him to Atlanta that September for John Drew, Freeman Williams and cash. He became the Hawks' all-time leading scorer.`,
  '1982:mvp-race': `Traded to Philadelphia, Moses Malone made the 76ers a 65-17 team and won MVP almost unanimously, the only player to win it in back-to-back seasons with two different teams. Larry Bird was second again.`,
  '1982:surprises': `Boston won five more games than Milwaukee, but the Bucks swept the Celtics in the second round, the first sweep in Celtics playoff history.`,
  '1983:contenders': `Boston and Los Angeles had the two best records, and the Bird and Magic rivalry finally reached the Finals. The teams traded wins all series and Boston took Game 7, 111-102, in what is often called one of the greatest Finals ever.`,
  '1983:draft-drama': `Houston took Virginia's Ralph Sampson, a three-time college player of the year, first; he was Rookie of the Year and an early All-Star before injuries took over. Portland's 14th pick, Clyde Drexler, had the best career in the class.`,
  '1983:mvp-race': `After three straight second-place finishes, Larry Bird won the MVP at 24.2 points, 10.1 rebounds and 6.6 assists for the 62-20 Celtics, with Bernard King second.`,
  '1983:surprises': `Philadelphia was the defending champion, but the 45-37 Nets beat the 76ers in the first round for the franchise's first NBA playoff series win. It would be their last until 2002.`,
  '1984:contenders': `Alex English and Doug Moe's free-flowing, high-scoring Nuggets had their best year, winning 52 games and the Midwest before the Lakers beat them 4-1 in the conference finals.`,
  '1984:draft-drama': `Hakeem Olajuwon went first and Portland took Sam Bowie second, the safe big-man picks of the day. Chicago got Michael Jordan at No. 3, and Philadelphia took Auburn's Charles Barkley fifth to add rebounding to the Erving-Malone team. Utah took John Stockton 16th, and a year later Karl Malone 13th; they played 18 seasons together.`,
  '1984:mvp-race': `Larry Bird raised his scoring to 28.7 points with 10.5 rebounds and 6.6 assists and won a second straight MVP with nearly every first-place vote, ahead of Magic Johnson.`,
  '1984:surprises': `A roof collapse at the Silverdome sent the Pistons to the Red Wings' arena for the rest of the season, and 36-46 Cleveland made the playoffs for the first time since 1978.`,
  '1985:contenders': `Houston's Twin Towers, Hakeem Olajuwon and Ralph Sampson, beat the Lakers in the West, then lost the Finals to Boston in six.`,
  '1985:draft-drama': `The first draft lottery decided who got Patrick Ewing, and the 24-58 Knicks won it. He gave them 15 years, 11 All-Star teams and 13 straight playoff trips, but no title.`,
  '1985:mvp-race': `The 67-15 Celtics are often ranked among the best teams ever, and Larry Bird won a third straight MVP, the only forward to do it, well ahead of scoring champion Dominique Wilkins.`,
  '1985:surprises': `The defending champion Lakers won 62 games and a Finals rematch with Boston looked set. Houston's Twin Towers beat them 4-1 instead, ending it on Ralph Sampson's off-balance shot at the buzzer, before the heavily favored Celtics won the Finals in six.`,
  '1986:contenders': `Both franchises, and both stars, had three titles in the decade, and Boston was still reeling from Len Bias's death. The 65-17 Lakers beat the champions in six, with Magic Johnson's junior sky hook deciding Game 4, and became the team of the 1980s.`,
  '1986:draft-drama': `The champion Celtics had the second pick thanks to an old Auerbach trade and took Len Bias, expected to carry the dynasty into the '90s and even rival Jordan. Two days later he died of an overdose, and with Reggie Lewis's death in 1993 those losses reshaped the East for a decade.`,

  // ── 1990s ───────────────────────────────────────────────────────
  '1986:mvp-race': `Michael Jordan scored 37.1 points a game for a 40-42 Bulls team, but Magic Johnson, at a career-high 23.9 points and 12.2 assists for the 65-17 Lakers, won his first MVP clearly ahead of him.`,
  '1986:surprises': `Seattle finished 39-43 and still upset the 55-win Mavericks and then Houston to reach the conference finals, where the Lakers swept them.`,
  '1987:contenders': `The Hawks, 57-game winners the year before, gave Boston everything it could handle in the second round. Atlanta lost Game 7 118-116, with Dominique Wilkins averaging 31.2 points in those playoffs.`,
  '1987:draft-drama': `San Antonio took Navy's David Robinson first knowing his service would keep him out until 1989-90. The same class brought Scottie Pippen at No. 5 and Reggie Miller at No. 11.`,
  '1987:mvp-race': `Michael Jordan led the league at 35.0 points on 53.5 percent shooting, was named Defensive Player of the Year and won his first MVP, with Larry Bird and Magic Johnson nearly tied behind him.`,
  '1987:surprises': `Boston had the better record, but Detroit beat the Celtics in six in the conference finals, the first time since 1983 that Boston did not represent the East in the Finals.`,
  '1988:contenders': `Detroit had lost a seven-game Finals to the Lakers the year before. This time the Bad Boys swept Los Angeles for their first title, then repeated against Portland in 1990.`,
  '1988:draft-drama': `The Clippers took Kansas star Danny Manning first, and he made two All-Star teams before injuries held him back. Mitch Richmond, the fifth pick, was Rookie of the Year and became a six-time All-Star.`,
  '1988:mvp-race': `Michael Jordan put up 32.5 points, 8.0 rebounds and 8.0 assists, but Magic Johnson's 22.5 points and 12.8 assists for the West-leading Lakers won a close vote.`,
  '1988:surprises': `The two-time champion Lakers swept Portland, Seattle and Phoenix and looked unstoppable, until injuries hit in the Finals and Detroit swept them for the Pistons' first title.`,
  '1989:contenders': `The Lakers had the West's best record but lost to Phoenix, so Portland met the defending champion Pistons. Detroit won in five and became only the third franchise to win back-to-back titles.`,
  '1989:draft-drama': `Sacramento took Pervis Ellison first and the Clippers took Danny Ferry second, and eight of the top ten picks came to be seen as busts. The value came later, with Shawn Kemp at 17 and Vlade Divac at 26.`,
  '1989:mvp-race': `Charles Barkley received more first-place votes, but Magic Johnson, at 22.3 points and 11.5 assists for the 63-19 Lakers in his first year without Kareem, won on total points, with Michael Jordan a close third.`,
  '1989:surprises': `Portland had gone 39-43 and entered the season with modest expectations. The Blazers won 59, beat San Antonio in seven and Phoenix in six, and reached the Finals.`,
  '1990:contenders': `Jordan's Bulls finally broke through, beating Magic Johnson's Lakers in five for the franchise's first title and starting the first of two three-peats under Phil Jackson.`,
  '1990:draft-drama': `Hank Gathers had been projected as a possible No. 1 pick before he died in March. The Nets took Syracuse's Derrick Coleman first, and Seattle's second pick, Gary Payton, became a nine-time All-Star and a Hall of Famer.`,
  '1990:mvp-race': `Michael Jordan averaged 31.5 points on 53.9 percent shooting for a 61-win Bulls team and won his second MVP comfortably over Magic Johnson.`,
  '1990:surprises': `For the first time since 1981 the Lakers were not the West's top seed, and they upset the heavily favored 63-win Trail Blazers to reach the Finals. Seventh-seeded Golden State knocked out the 55-win Spurs.`,
  '1991:contenders': `Portland went a franchise-best 63-19 in 1990-91 but lost the conference finals to the Lakers, then got back to the Finals in 1992 and lost to Jordan's Bulls in six.`,
  '1991:draft-drama': `Charlotte took Larry Johnson first and he was Rookie of the Year, while Denver's fourth pick, Dikembe Mutombo, became a four-time Defensive Player of the Year. Third pick Billy Owens refused to sign with Sacramento and was traded for Mitch Richmond, who turned out far better.`,
  '1991:mvp-race': `The Bulls went 67-15 and Michael Jordan won a second straight MVP at 30.1 points, with Clyde Drexler second. When the two met in the Finals, the media sold it as the next Magic and Bird.`,
  '1991:surprises': `In the first week of November 1991, Don Nelson broke up Golden State's Run TMC trio by trading Mitch Richmond for Billy Owens to get bigger, and Magic Johnson announced he had HIV and retired.`,
  '1992:contenders': `Phoenix traded for Charles Barkley, won a franchise-record 62 games and reached the Finals, where Jordan's Bulls beat the Suns in six for a third straight title.`,
  '1992:draft-drama': `Orlando, a three-year-old expansion team, won the lottery and took Shaquille O'Neal, who was Rookie of the Year and made the Magic 20 wins better right away.`,
  '1992:mvp-race': `Charles Barkley won MVP in his first season in Phoenix, at 25.6 points, 12.2 rebounds and 5.1 assists for a 62-win team, then lost the Finals to Michael Jordan.`,
  '1992:surprises': `Charlotte, a 20-62 expansion team four years earlier, made its first playoffs behind Larry Johnson and Alonzo Mourning and upset the Celtics in the first round, before the Knicks beat them 4-1.`,
  '1993:contenders': `Pat Riley's physical, defensive Knicks, built around Patrick Ewing, beat Indiana in seven to reach the Finals. Hakeem Olajuwon's 58-win Rockets beat them in another seven-game series for Houston's first title, with Olajuwon outplaying Ewing in a 90-84 Game 7.`,
  '1993:draft-drama': `Orlando won the lottery again and traded the top pick, Chris Webber, to Golden State for third pick Penny Hardaway and future picks, giving Shaq a playmaking guard. The pair won 50 games in Hardaway's rookie year.`,
  '1993:mvp-race': `Hakeem Olajuwon won MVP for a franchise-best 58-win Houston team, then added the title and Finals MVP. With Jordan gone, Scottie Pippen was the Bulls' whole offense and finished third, at 22 points, 8.7 rebounds and 5.6 assists for a 55-win team.`,
  '1993:surprises': `Nobody expected Jordan to walk away at 30 after three straight titles, months after his father's murder. The bigger surprise was what came next: Pippen kept the Bulls at 55 wins and the East's third seed, and it took the Knicks seven games to put them out. In Atlanta, the Hawks traded Dominique Wilkins, their all-time leading scorer, in the middle of a 57-win season, and eighth-seeded Denver knocked out top-seeded Seattle in overtime of Game 5.`,
  '1994:contenders': `The Bulls were a Pippen-led team scrapping for position until March, when Jordan's two-word fax, "I'm back," changed the race. He played 17 games in No. 45, but Orlando, in only its sixth season, beat them in the second round and Indiana in seven to reach the Finals, where Houston swept the Magic. With Jordan back for a full year and Rodman added, the next Bulls team went 72-10.`,
  '1994:draft-drama': `Dallas added Jason Kidd to Jim Jackson and Jamal Mashburn and looked like it had its big three of the future, with Kidd's triple-doubles helping the team improve by 23 wins. Injuries, friction between Kidd and Jackson, three owners and four coaches broke them up before they ever played 82 games together. Detroit, rebuilding after Isiah Thomas retired, took Grant Hill third, and he shared Rookie of the Year with Kidd.`,
  '1994:mvp-race': `David Robinson led the 62-20 Spurs to the league's best record and won MVP with 73 first-place votes, far ahead of Shaquille O'Neal. Then the Rockets beat San Antonio in the conference finals, and Robinson admitted Hakeem Olajuwon had outplayed him.`,
  '1994:surprises': `Houston slipped to 47-35 and the West's sixth seed even after trading for Clyde Drexler, then beat Utah, Phoenix and San Antonio and swept Orlando to repeat as champions.`,
  '1995:contenders': `The 72-win Bulls were the overwhelming favorite, and the debate was whether expansion had watered the league down enough to make it easy. In the Finals, Seattle's George Karl kept Defensive Player of the Year Gary Payton off Jordan until the Sonics were down 0-3; once he made the switch, Seattle won two straight before Chicago closed it out in six.`,
  '1995:draft-drama': `Minnesota, which had never won more than 29 games, took a chance on Kevin Garnett at No. 5, only the fourth player to go straight from high school to the pros.`,
  '1995:mvp-race': `Michael Jordan, back for a full season, led the league at 30.4 points for a 72-10 Bulls team and won a fourth MVP with 109 first-place votes, then swept the All-Star, MVP and Finals MVP awards.`,
  '1995:surprises': `Pat Riley left the Knicks to become president and coach of a Heat team with little history, and within months he had Alonzo Mourning and Tim Hardaway.`,
  '1996:contenders': `Behind the Bulls, the East's fiercest fight was Pat Riley's new team against his old one. The Knicks led Miami 3-1 until a brawl and the suspensions that followed, and the Heat won Game 7, their only win in four straight playoff meetings. Houston added Charles Barkley to Olajuwon and Drexler and reached the West finals, where Utah beat them. Utah won 64 games with MVP Karl Malone and reached the Finals, where the Bulls won in six.`,
  '1996:draft-drama': `Philadelphia, coming off an 18-64 season and a string of picks that hadn't worked, took Allen Iverson first, and he was Rookie of the Year. Minnesota took Ray Allen fifth and traded him straight to Milwaukee for the player it really wanted, Stephon Marbury, Garnett's friend from high school, and the Wolves won 40 games with a real direction for the first time. The Lakers traded starting center Vlade Divac for the 13th pick, high schooler Kobe Bryant.`,
  '1996:mvp-race': `Karl Malone won MVP for the 64-win Jazz, and then Jordan's Bulls beat Utah in the Finals.`,
  '1996:surprises': `Shaquille O'Neal left the 60-win Magic for the Lakers when Orlando wouldn't go past $13.5 million a year, and Charlotte, after a franchise-best 54 wins, was swept by the Knicks in the first round.`,
  '1997:contenders': `Everyone knew the Bulls were old, tired and probably on their last run. Reggie Miller's Pacers, the most balanced team he ever had, led Game 7 of the conference finals in the fourth quarter and still lost, and Jordan's steal and jumper in Salt Lake City sealed a sixth title.`,
  '1997:draft-drama': `San Antonio, normally a 50-win team, fell to 20 wins after David Robinson's foot injury, and nobody gave them much chance of winning a second lottery. They won it and took Tim Duncan, the start of a dynasty and of the story that the Spurs were as lucky as they were smart.`,
  '1997:mvp-race': `Karl Malone had edged Michael Jordan in a tight MVP race the year before. With the Bulls and Jazz both 62-20, Jordan led the league at 28.7 points and took the award back clearly.`,
  '1997:surprises': `A year after Dikembe Mutombo left, Denver went 11-71, the worst winning percentage in franchise history.`,
  '1998:contenders': `With Jordan retired and the Bulls broken up, the lockout-shortened 50-game season was wide open. Miami, the East's top seed, made its title intentions clear and lost to the eighth-seeded Knicks. San Antonio lost one game in the West and beat New York for the title, though many put an asterisk on it.`,
  '1998:draft-drama': `Dallas looked bad enough to fold, and Don Nelson took a leap of faith on draft night, trading for a skinny German teenager named Dirk Nowitzki and Phoenix's backup point guard, Steve Nash. Toronto swapped Antawn Jamison's rights for Vince Carter, who was Rookie of the Year. In Chicago, Jerry Krause tore down the six-time champions to bet on youth and picks, and the Bulls went 13-37 in the lockout season, then 17-65 and 15-67.`,
  '1998:mvp-race': `Alonzo Mourning finished second in MVP voting and won Defensive Player of the Year for the top-seeded Heat, then went out in the first round to the eighth-seeded Knicks.`,
  '1998:surprises': `The post-Jordan East was supposed to belong to Miami or Indiana. The eighth-seeded Knicks, who stumbled into the playoffs, beat both, with Allan Houston's dagger finishing the Heat, and kept winning without an injured Patrick Ewing. Sacramento traded Mitch Richmond for Chris Webber, added Vlade Divac and coach Rick Adelman, and went from also-rans to the 'Greatest Show on Court.'`,
  '1999:contenders': `Phil Jackson arrived from Chicago with the triangle offense and got Shaq and Kobe working together. Reggie Miller finally reached the Finals at 34, but MVP Shaquille O'Neal averaged nearly 40 and the Lakers began a run of three straight titles.`,
  '1999:draft-drama': `Vancouver took Steve Francis second and traded him straight to Houston for veterans and future assets, a sign of a franchise chasing short-term wins in its final years in Canada.`,
  '1999:mvp-race': `This was Shaquille O'Neal's MVP season, and he capped it by averaging nearly 40 in the Finals against Indiana.`,

  // ── 2000s ───────────────────────────────────────────────────────
  '1999:surprises': `San Antonio entered the playoffs as defending champion, but without the injured Tim Duncan the Spurs lost 3-1 to Phoenix in the first round.`,
  '2000:contenders': `Allen Iverson dragged a Sixers team with almost no spacing to the Finals, with Dikembe Mutombo winning Defensive Player of the Year and Aaron McKie Sixth Man. They needed Game 7 to get past George Karl's 52-win "Let It Fly" Bucks, and won one game against the Lakers.`,
  '2000:draft-drama': `New Jersey took Kenyon Martin first in what came to be called the worst draft ever: only Martin, Jamaal Magloire and second-rounder Michael Redd made an All-Star team, once each, and fifth pick Mike Miller was Rookie of the Year.`,
  '2000:mvp-race': `The 76ers opened 10-0 and led the East, and Allen Iverson led the league at 31.1 points and won MVP over Tim Duncan and Shaquille O'Neal, the shortest and lightest player to win it.`,
  '2000:surprises': `Miami lost Alonzo Mourning to a rare kidney disease for nearly the whole season, and Minnesota's secret deal with Joe Smith cost the Wolves five first-round picks, a $3.5 million fine and a suspension for their owner.`,
  '2001:contenders': `Jason Kidd, acquired from Phoenix for Stephon Marbury, turned the Nets into a 52-win team and the East's Finals representative. The Lakers swept them in the 2002 Finals, and they lost the 2003 Finals to San Antonio. In the West, 61-win Sacramento took the top seed and lost a contentious seven-game conference finals to the Lakers.`,
  '2001:draft-drama': `Draft night was a bet on potential: Michael Jordan made Kwame Brown the first high schooler taken No. 1, high schoolers Tyson Chandler and Eddy Curry went second and fourth, and Pau Gasol rose late to third. Gasol was Rookie of the Year and became the best of the class; Brown and Curry rank 17th and 16th in win shares. European point guards weren't trusted, and Tony Parker's first workout went so badly Popovich didn't want him back; Boston nearly took him before its owners balked. He slid to San Antonio at No. 28 and became the starter anyway.`,
  '2001:mvp-race': `Jason Kidd's 14.7 points and 9.9 assists for New Jersey made it close, but Tim Duncan, at 25.5 points and 12.7 rebounds, won his first MVP, with Shaquille O'Neal third.`,
  '2001:surprises': `Michael Jordan, 38 and already running the Wizards' front office, came back to play for a team that had gone 19-63. He averaged 22.9 points and filled the arena, but Washington missed the playoffs both years.`,
  '2002:contenders': `The 60-win Mavericks thought it was their year, but after Nowitzki sprained his knee early in the West finals, San Antonio beat them in six and went on to the title. In NBA.com's first preseason GM Survey, 61.5% picked the Lakers to four-peat and the Spurs got 3.8% of the title votes.`,
  '2002:draft-drama': `Houston took 7-foot-6 Chinese center Yao Ming first, a pick that brought the NBA an enormous audience in China. In NBA.com's preseason GM Survey, GMs split between Yao Ming and Jay Williams for Rookie of the Year; Amare Stoudemire, a 7.7% pick, won it.`,
  '2002:mvp-race': `Kevin Garnett put up 23.0 points, 13.4 rebounds and 6.0 assists, but Tim Duncan's 23.3 points and 12.9 rebounds for the 60-22 Spurs won him a second straight MVP, and he finished the year as champion and Finals MVP.`,
  '2002:surprises': `The three-time champion Lakers lost to San Antonio in the second round, Minnesota lost in the first round for the seventh straight time, and 42-40 Orlando blew a 3-1 lead to top-seeded Detroit. In NBA.com's preseason GM Survey, GMs' most improved pick, Atlanta (47.8%), won just two more games than the year before.`,
  '2003:contenders': `The Lakers added Karl Malone and Gary Payton for one more ring, the Pacers won 61, Minnesota finally broke through, and Detroit was dismissed as the best of a feeble conference. The Pistons beat Indiana in a six-game slugfest, then beat the Lakers' would-be superteam in five, one of the biggest Finals upsets. In NBA.com's preseason GM Survey, GMs picked the Lakers (52.4%) and gave Detroit no title votes; the Pistons beat them 4-1.`,
  '2003:draft-drama': `LeBron James, the most hyped high school player ever, went first to his home-state Cavaliers. Denver, coming off 17-65, took Carmelo Anthony third and made the playoffs in his rookie year. Miami slipped to fifth, a letdown at the time, took Dwyane Wade almost by accident, and saw him shine as a rookie. In NBA.com's preseason GM Survey, 81% of GMs picked LeBron over Carmelo for Rookie of the Year, and he won it.`,
  '2003:mvp-race': `Kevin Garnett, at 24 and 14 for a 58-win team that took the top seed in the West, was the clear MVP, and a young LeBron James called him the best player in the league. In NBA.com's preseason GM Survey, GMs split between Duncan and Shaq for MVP; Garnett, only an also-ran in the survey, won it.`,
  '2003:surprises': `Detroit, the team that took Darko Milicic over Carmelo Anthony, was supposed to come up short in the Finals again. With Ben Wallace their only All-Star, they beat the Lakers in five. In Memphis, Hubie Brown took over a losing team and won 50 games and Coach of the Year.`,
  '2004:contenders': `Indiana started as the East favorite until the Malice at the Palace wrecked its season, and Miami's trade for Shaquille O'Neal made the Heat a co-favorite with Detroit. The Heat won nearly 60, but Wade's rib injury cost them Game 7 against the defending champion Pistons, who then took San Antonio to Game 7 of the Finals and lost 81-74. In the West, Steve Nash's 62-win Suns knocked out the Mavericks who had let him go. In NBA.com's preseason GM Survey, GMs picked the Spurs (45.2%) over the Pistons (33.3%), and that was the Finals: Spurs in seven.`,
  '2004:draft-drama': `Orlando, 21-61 amid Tracy McGrady's frustrations, won the lottery and took 18-year-old Dwight Howard straight out of high school. In NBA.com's preseason GM Survey, GMs' Rookie of the Year order (Okafor, Gordon, Howard) came true.`,
  '2004:mvp-race': `Dallas had decided Steve Nash, about to turn 30, was an injury risk not worth big money. He won MVP in his first season in Phoenix, ahead of Shaquille O'Neal, who finished second in his first year in Miami. Nash's seven-seconds-or-less Suns went 62-20, up from 29-53. In NBA.com's preseason GM Survey, GMs picked Shaq for MVP (57.1%) and left Steve Nash off; Nash won it.`,
  '2004:surprises': `Gilbert Arenas, Antawn Jamison and Caron Butler took Washington to 45 wins and its first playoff trip since 1997, and the fifth-seeded Wizards upset the fourth-seeded Bulls. Phoenix, 29-53 the year before, won 62 games with Steve Nash and Mike D'Antoni's up-tempo offense.`,
  '2005:contenders': `Detroit won 64 games, and Dallas finally beat the defending champion Spurs in a Game 7 that felt like its time had come. Miami, pieced together from aging stars, with Riley back on the bench, was the underdog in the Finals and down 0-2. Then Wade took over and the Heat won four straight. In NBA.com's preseason GM Survey, 76.9% of GMs picked the Spurs to repeat; Dallas got no West votes, beat them, and lost the Finals to Miami.`,
  '2005:draft-drama': `New Orleans took Chris Paul fourth just before Hurricane Katrina sent the team to Oklahoma City, and he was a near-unanimous Rookie of the Year. In NBA.com's preseason GM Survey, GMs leaned Bogut (40%) over Chris Paul (36%) for Rookie of the Year; Paul won it.`,
  '2005:mvp-race': `Kobe Bryant led the league at 35.4 points and LeBron James scored 31.4, but Steve Nash's 18.8 points and league-best 10.5 assists for the 54-win Suns won him a second straight MVP. Bryant had the second-most first-place votes yet finished fourth. In NBA.com's preseason GM Survey, GMs picked Duncan (58.3%) and again left Steve Nash off; Nash won his second MVP.`,
  '2005:surprises': `Dallas went into the Finals as the favorite, won the first two games and had its parade plans leaked, then lost four straight to Wade's Heat. The Clippers, a perennial afterthought, came within a hair of the conference finals.`,
  '2006:contenders': `The 67-win Mavericks were the favorite among the West's three powers, with the East at rock bottom. After the eighth-seeded Warriors knocked them out, it became a two-team race between the Spurs and Suns, swung by the suspensions after Robert Horry's hip check. San Antonio beat LeBron's overmatched Cavaliers in the Finals. In NBA.com's preseason GM Survey, GMs' title pick, the Spurs, won it; Cleveland, with no East votes, was the team they swept.`,
  '2006:draft-drama': `Minnesota took Brandon Roy sixth and traded him on draft night for Randy Foye, seen then as the safer, more popular pick with Roy's knee in question. Roy won Rookie of the Year; Foye became a role player. In NBA.com's preseason GM Survey, GMs' Rookie of the Year pick, Brandon Roy (44.4%), won it.`,
  '2006:mvp-race': `Dirk Nowitzki won MVP for a 67-win team, then accepted the trophy after losing to an eighth seed, and the "soft superstar" label started to stick. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP, with Dirk third; Dirk won it, then Dallas lost in the first round to Golden State.`,
  '2006:surprises': `The defending champion Heat were swept in the first round by the young Bulls, the first sweep of a champion since the 1950s, and the 67-win Mavericks lost to the eighth-seeded Warriors. Third-seeded Toronto, back in the playoffs for the first time since 2002, lost to the sixth-seeded Nets. Out of a weak East, a 22-year-old LeBron carried a thin Cavaliers roster to the Finals. Utah, rebuilt around Deron Williams and Carlos Boozer, won the Northwest and reached the conference finals.`,
  '2007:contenders': `After the biggest regular-season turnaround ever, Boston's new big three was fully expected to win the title, and it did, though two seven-game series against weaker teams were an early warning. In the West, the Lakers' midseason trade for Pau Gasol, criticized as a giveaway by Memphis, took them to the Finals, and Chris Paul's Hornets won 56 games. In NBA.com's preseason GM Survey, even after the Garnett trade, only 3.7% of GMs picked Boston to win the title; the Celtics won 66 and the championship.`,
  '2007:draft-drama': `The top pick was debated between Greg Oden and Kevin Durant, with doubts about Durant's frame. Seattle took him second, traded Ray Allen to Boston that night, and Durant won Rookie of the Year. Oden didn't play a minute. Microfracture surgery that September was the start of years of knee trouble for Oden in Portland, where he played only 82 games. In NBA.com's preseason GM Survey, 92.6% of GMs picked Durant for Rookie of the Year, and he won it.`,
  '2007:mvp-race': `Boston won 66 games and Chris Paul led the league in assists for the 56-win Hornets, but Kobe Bryant won his only MVP for the West-leading Lakers, ahead of Paul and Kevin Garnett. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP, with Kobe third; Kobe won it.`,
  '2007:surprises': `The eighth-seeded Hawks, built on Joe Johnson, Josh Smith and Al Horford, took the top-seeded Celtics to seven games in the first round and won all three at home.`,
  '2008:contenders': `Boston started 27-2 and Celtics-Lakers looked like the Finals for years to come, until Kevin Garnett's knee injury in February. Orlando beat the Celtics in seven in the second round, then upset LeBron James's Cavaliers 4-2 before losing the Finals to the Lakers in five. Denver, remade by the Chauncey Billups trade, won 54 games and reached the West finals. In NBA.com's preseason GM Survey, GMs' Lakers pick (46.2%) won the title; Orlando, a 3.7% East pick, was the Finals opponent.`,
  '2008:draft-drama': `Sam Presti was criticized for taking Russell Westbrook fourth, a defense-first guard projected to go later. A year later he took James Harden despite talk he was too slow, having stashed Serge Ibaka at 24. Three future MVPs in three straight drafts. In NBA.com's preseason GM Survey, GMs picked Beasley and Oden for Rookie of the Year and gave Derrick Rose no votes; Rose won it.`,
  '2008:mvp-race': `Cleveland went a franchise-record 66-16, and LeBron James won his first MVP with 109 first-place votes, well ahead of Kobe Bryant and Dwyane Wade. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (55.6%), and he won it.`,
  '2008:surprises': `Orlando's upset of LeBron James's Cavaliers sent the Magic to the Finals. In Detroit, the Chauncey Billups-for-Allen Iverson trade that was meant to refresh an aging core disrupted it instead, and the Pistons slipped to 39-43.`,
  '2009:contenders': `LeBron's MVP Cavaliers and an even better Orlando were the East favorites, and the old Celtics were written off at 50 wins. Boston beat both in six behind a breakout Rajon Rondo, then lost a fierce seven-game Finals to the Lakers. Phoenix, back to its up-tempo style under Alvin Gentry, won 54 and lost the West finals to the Lakers 4-2. In NBA.com's preseason GM Survey, GMs picked the Lakers to repeat (60.7%) and Boston to win the East; both held.`,
  '2009:draft-drama': `With no sure thing after Blake Griffin, Memphis took Hasheem Thabeet second despite doubts about his offense. He lasted five seasons, while the next pick, James Harden, became the best player in the class. Minnesota held four first-round picks and took two point guards, Ricky Rubio and Jonny Flynn, right in front of Stephen Curry, a choice many executives would have made then. The Clippers won the lottery and Blake Griffin, seen as a magic bullet, and he broke his kneecap before his rookie season. In NBA.com's preseason GM Survey, 79.3% of GMs picked Blake Griffin for Rookie of the Year; Tyreke Evans won it and Stephen Curry was second.`,
  '2009:mvp-race': `Kevin Durant became the youngest scoring champion ever and finished second in MVP voting, leading a 50-win Thunder team that had won 23 games the year before. In NBA.com's preseason GM Survey, GMs picked LeBron to repeat as MVP (69%), and he did.`,
  '2009:surprises': `Two teams outran their expectations: the eighth-seeded Thunder, seen as a mismatch for the champion Lakers, came seconds from forcing a Game 7, and the written-off Celtics made the Finals. At the other end, the Nets went 12-70, the worst record in franchise history, and Gilbert Arenas's Wizards career ended with a 50-game suspension over guns in the locker room.`,

  // ── 2010s ───────────────────────────────────────────────────────
  '2010:contenders': `LeBron and Chris Bosh joined Wade, and the consensus was that Miami had built something close to unbeatable, with at least three titles expected. After a 9-8 start, the Heat won 58, beat Boston and Derrick Rose's 62-win Bulls, and were heavy favorites in the Finals. Dallas, which nobody took seriously, beat them in six. Boston's injury-hit gamble on Shaq and OKC's push to the West finals were the other stories of the race. In NBA.com's preseason GM Survey, GMs picked the Lakers (63%) and gave Dallas one vote to win the West; the Mavericks swept the Lakers and won it all.`,
  '2010:draft-drama': `Washington took John Wall first to start a rebuild around his speed. Paul George was a raw, little-known pick at No. 10 that few saw as a franchise cornerstone. Minnesota took Wesley Johnson fourth, ahead of DeMarcus Cousins, Gordon Hayward and George, and the Clippers gave away the pick that became Kyrie Irving because their GM wasn't high on the draft. In NBA.com's preseason GM Survey, GMs picked John Wall for Rookie of the Year (67.9%); Blake Griffin won it unanimously.`,
  '2010:mvp-race': `Miami's 58 wins counted as an underperformance, which kept LeBron from the award. Derrick Rose, 22, won it as the league's youngest MVP for a 62-win Bulls team, then LeBron took the Rose assignment in the conference finals and Miami won in five. In NBA.com's preseason GM Survey, two-thirds of GMs picked Durant for MVP and none picked Derrick Rose, who won it.`,
  '2010:surprises': `Almost nobody picked Dallas. The Mavericks swept the two-time champion Lakers, then beat the Heat big three in six, erasing Dirk's old failures overnight. The eighth-seeded Grizzlies also beat the 61-win Spurs, and the verdict was that San Antonio's dynasty was finished. Utah lost Jerry Sloan, who resigned after 23 seasons following an argument with Deron Williams, and traded Williams to the Nets thirteen days later.`,
  '2011:contenders': `After the 2011 collapse, it was title or bust for Miami. The young Thunder took over the West, beating the champion Mavericks, the Lakers and the 20-straight-win Spurs, and went into the Finals slightly favored. Miami, pushed by Indiana and Boston, won in five, and LeBron got his first ring. In NBA.com's preseason GM Survey, GMs picked Miami (74.1%) and OKC to win the West, and that was the Finals: Heat in five.`,
  '2011:draft-drama': `With the Spurs declared dead, San Antonio traded George Hill for the 15th pick, Kawhi Leonard, framed as help for the wing rotation. It made sense for Indiana at the time, and Leonard turned out to be the best player in the draft. In NBA.com's preseason GM Survey, GMs picked Kyrie Irving for Rookie of the Year (63%), and he won it.`,
  '2011:mvp-race': `LeBron won his third MVP as Miami's clear first option. Durant was second again, and Chris Paul finished third in his first Clippers season. In NBA.com's preseason GM Survey, GMs split Durant (55.6%) and LeBron (44.4%) for MVP; LeBron won it.`,
  '2011:surprises': `The lockout season was full of things nobody planned for. In February an undrafted Jeremy Lin came off the Knicks' bench and set off Linsanity, and the Bobcats finished 7-59, the worst winning percentage in NBA history. Then Derrick Rose tore his ACL in the first round, and nothing went to script after that: the old Celtics took Miami to seven in the conference finals, the Pacers, projected below .500, went up 2-1 on the Heat, and the Thunder came back from 0-2 to end the Spurs' 20-game streak.`,
  '2012:contenders': `With no Rose and no contending Celtics, Miami was expected to cruise. It won 66 games with a 27-game streak, but Indiana pushed it to seven, and San Antonio, written off as old and boring, was seconds from the title in Game 6 before Ray Allen's shot. OKC traded James Harden before the season, and its 60-win team lost Westbrook to a torn meniscus in the first round. Memphis's Grit and Grind team won 56 and reached the West finals. In NBA.com's preseason GM Survey, GMs picked Miami to repeat (70%), which held, and the Howard-Nash Lakers to win the West (60%), who were swept in round one.`,
  '2012:draft-drama': `New Orleans won the lottery with only the third-worst record and took Anthony Davis first. Portland took Damian Lillard sixth, and he was the unanimous Rookie of the Year. In NBA.com's preseason GM Survey, GMs picked Anthony Davis for Rookie of the Year (76.7%); Damian Lillard won it unanimously.`,
  '2012:mvp-race': `LeBron won 66 games and a near-unanimous MVP, with Carmelo Anthony getting the one dissenting vote. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (66.7%), and he nearly won it unanimously.`,
  '2012:surprises': `Most predictions had the Knicks beating Indiana and setting up Melo vs. LeBron. Roy Hibbert's block on Carmelo ended New York, and the Pacers took the Heat to seven. In the West, sixth-seeded Golden State knocked out 57-win Denver. Vivek Ranadive's group bought the Kings for a then-record $534 million, ending a possible move to Seattle.`,
  '2013:contenders': `The 33-7 Pacers were billed as Miami's challenger and fell apart; the Heat, invincible-looking in a weak East, made a fourth straight Finals. San Antonio spent the year on a redemption mission, beat OKC in the West finals, then crushed Miami in five in what's called perhaps the greatest display of team basketball ever. In NBA.com's preseason GM Survey, GMs picked Miami to three-peat (75.9%) and gave the Spurs 6.9%; San Antonio beat the Heat 4-1.`,
  '2013:draft-drama': `Most mock drafts had Nerlens Noel first, and Cleveland shocked everyone by taking Anthony Bennett, who lasted four seasons; Noel fell to sixth. Boston traded Pierce, Garnett and Terry to Brooklyn for unprotected picks in 2014, 2016 and 2018. In the moment Brooklyn got a contender and Boston got time; one of those picks became Jaylen Brown. The Celtics took Marcus Smart sixth in their one true rebuilding year. Milwaukee used the 15th pick on Giannis Antetokounmpo, a raw 18-year-old from Greece, who became an MVP. Utah traded up for Trey Burke at No. 9 and took Rudy Gobert 27th; Gobert became a three-time Defensive Player of the Year. In NBA.com's preseason GM Survey, GMs picked Victor Oladipo for Rookie of the Year (80%); Michael Carter-Williams won it.`,
  '2013:mvp-race': `Durant had finished second to LeBron three times and said he was "done with being second." With Westbrook hurt for half the year, he averaged 32 and scored 25 or more in 41 straight games. It was the one year of LeBron's Miami peak when someone else looked better, and voters agreed. His "real MVP" speech became a cultural moment. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (69%); Durant won it.`,
  '2013:surprises': `Fifth-seeded Portland upset Houston in six in the first round, with Damian Lillard averaging 25.5 points.`,
  '2014:contenders': `The Hawks won 60 with four All-Stars and were called the Spurs of the East, but nobody believed in them come May. LeBron's new Cavs lost only twice on the way to the Finals. In the West, Chris Paul's Clippers led Houston 3-1 and lost three straight, and Steve Kerr's 67-win Warriors, in his first year as a head coach, won the title. In NBA.com's preseason GM Survey, GMs picked the Spurs (46.2%) and expected another Spurs-LeBron Finals; Golden State, at 3.8%, won 67 games and the title.`,
  '2014:draft-drama': `Joel Embiid might have gone first before a foot fracture just before the draft. Cleveland took Andrew Wiggins, Milwaukee took Jabari Parker, whom some saw as more NBA-ready, and Philadelphia took the chance on Embiid third; of the three, Embiid has the most win shares. When LeBron went back to Cleveland, the Cavs traded No. 1 pick Andrew Wiggins for Kevin Love. Wiggins, hyped as Kobe's protege, won Minnesota's first Rookie of the Year. Denver used the 41st pick on Nikola Jokic and left him in Serbia for a year. In NBA.com's preseason GM Survey, GMs picked Jabari Parker for Rookie of the Year (75%); Andrew Wiggins won it.`,
  '2014:mvp-race': `Steph Curry won his first MVP for a 67-win Warriors team that went on to win the title. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (67.9%) and gave Curry no votes; Curry won it.`,
  '2014:surprises': `Atlanta jumped from 38 wins to 60 to take the top seed, and Boston's deadline trade for Isaiah Thomas, a 5-9 guard nobody saw as an All-Star, set up the Celtics' return. In NBA.com's preseason GM Survey, 92.9% of GMs picked OKC to win its division and 7.4% picked Atlanta to win the Southeast; OKC missed the playoffs and the Hawks won 60.`,
  '2015:contenders': `The 73-win Warriors and unanimous MVP Steph Curry were overwhelming favorites after breaking the Bulls' record. OKC upset the Spurs and led Golden State 3-1 in the West finals before losing three straight. The Warriors then led Cleveland 3-1 in the Finals, and the Cavs became the first team to come back from that in a Finals. In NBA.com's preseason GM Survey, only 17.9% of GMs picked the champion Warriors to repeat; they won 73, and the GMs' pick, Cleveland, beat them in seven.`,
  '2015:draft-drama': `Knicks fans booed Kristaps Porzingis at No. 4, and Phil Jackson called him a great risk; he finished second to Karl-Anthony Towns for Rookie of the Year. Phoenix took Kentucky's Devin Booker 13th; he was the one bright spot of a 23-59 rookie year and became the Suns' centerpiece. In NBA.com's preseason GM Survey, GMs picked Jahlil Okafor for Rookie of the Year (44.8%); Karl-Anthony Towns won it unanimously.`,
  '2015:mvp-race': `Steph Curry was the first unanimous MVP, leading the league at 30.1 points with a record 402 threes for a team that won 73 games. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP and had Curry tied for fifth (7.1%); Curry won it unanimously.`,
  '2015:surprises': `Cleveland came back from 3-1 down against the 73-win Warriors, the first Finals comeback of its kind, and ended the city's 52-year wait for a major title. Kobe Bryant's last Lakers team went 17-65, the worst in franchise history, before he scored 60 in his final game.`,
  '2016:contenders': `Durant leaving OKC for Golden State stunned the league and decided the race before it started: the Warriors beat Cleveland in the Finals in five and again the next year, with Durant Finals MVP both times. The rest of the East fell further behind Cleveland, which lost only once on the way to a Finals it couldn't win. Kawhi Leonard's injury in the West finals, which many fans think changed NBA history, started the saga that ended with him traded to Toronto. In NBA.com's preseason GM Survey, 69% of GMs picked the Durant Warriors over Cleveland in a third straight Finals, and Golden State won 4-1.`,
  '2016:draft-drama': `It was billed as a two-player draft, and Ben Simmons and Brandon Ingram went one-two as expected; Jaylen Brown, Jamal Murray, Domantas Sabonis and Pascal Siakam all ended up with more win shares. Boston used the Brooklyn pick at No. 3 on Jaylen Brown and chased Kevin Durant in free agency, which would have brought back title hopes in one of the shortest rebuilds ever. Durant chose Golden State. In Philadelphia, Sam Hinkie resigned after a 10-72 season with a 13-page letter defending The Process, and his successors took Ben Simmons first. In NBA.com's preseason GM Survey, GMs picked Kris Dunn for Rookie of the Year (46.7%); Malcolm Brogdon won it.`,
  '2016:mvp-race': `Without Durant, OKC was supposed to crater. Russell Westbrook averaged a triple-double, breaking Oscar Robertson's record, and beat out James Harden. The award has been questioned since. Isaiah Thomas, whom nobody had pictured as an All-Star, scored nearly 30 a game and got into the MVP conversation. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (46.7%) with Westbrook second; Westbrook won it.`,
  '2016:surprises': `Westbrook's triple-double season and Isaiah Thomas carrying Boston to the East's top seed were the year's shocks. Both teams' seasons still ended against the favorites. Sacramento traded three-time All-Star DeMarcus Cousins to New Orleans for Buddy Hield and others.`,
  '2017:contenders': `Houston traded for Chris Paul, won 65 games and led the West, and took Golden State to seven in the West finals after Paul hurt his hamstring. OKC added Paul George and Carmelo Anthony to Westbrook, a big three that looked better on paper than people believed, and Donovan Mitchell's Jazz beat them in six. Toronto won a franchise-record 59 games and was knocked out by LeBron's Cavaliers for the third straight year. In NBA.com's preseason GM Survey, 93% of GMs picked the Warriors, the most in survey history, and they swept the Cavs.`,
  '2017:draft-drama': `Philadelphia traded up with Boston for Markelle Fultz, seen as the clear-cut best prospect, and graded an A; Boston took Jayson Tatum third, and Tatum became one of the class's best while Fultz ranks 22nd in win shares. On draft night Chicago traded Jimmy Butler to Minnesota for Zach LaVine, Kris Dunn and the No. 7 pick, Lauri Markkanen, to angry fans. Butler got the Wolves to the playoffs for the first time in 14 years, then blew it up. Miami took Bam Adebayo 14th after he cursed out the front office during switching drills. Utah got Donovan Mitchell at No. 13, and he finished second to Ben Simmons for Rookie of the Year. Sacramento took De'Aaron Fox fifth and, a year later, Marvin Bagley III second. In NBA.com's preseason GM Survey, GMs picked Lonzo Ball for Rookie of the Year (62%); Ben Simmons won it.`,
  '2017:mvp-race': `James Harden won MVP at 30.4 points and 8.8 assists for a 65-win Rockets team built on Daryl Morey's threes-and-layups approach. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (50%) with Harden fourth (7%); Harden won it.`,
  '2017:surprises': `With Hayward hurt on opening night and Irving out for the playoffs, Boston was supposed to go out early. Jaylen Brown and Jayson Tatum took the Celtics to Game 7 of the conference finals instead. In the West, Anthony Davis averaged 33 points as the Pelicans swept Portland.`,
  '2018:contenders': `With LeBron gone west, the East had four real contenders for the first time in decades: Toronto with Kawhi Leonard, Philadelphia, a 60-win Milwaukee team and a Boston team expected to win 60 with Kyrie and Hayward back. The Celtics fell apart, and Toronto beat Milwaukee and then Golden State for its first title. In NBA.com's preseason GM Survey, GMs picked the Warriors (87%) and Boston in the East (90%); Toronto, with no title votes, won the championship.`,
  '2018:draft-drama': `Deandre Ayton was the consensus top pick, and many doubted Luka Doncic for skipping college. Sacramento took Marvin Bagley III second, a pick SI called relatively safe while warning the Kings might rue passing on Doncic. Dallas traded up for Doncic, the doubts disappeared almost immediately, and he was Rookie of the Year; Bagley ranks 22nd in the class in win shares. In NBA.com's preseason GM Survey, GMs picked Luka Doncic for Rookie of the Year (43%), and he won it.`,
  '2018:mvp-race': `Giannis Antetokounmpo won his first MVP at 27.7 points, 12.5 rebounds and 5.9 assists for a 60-win Bucks team, then won again the next season. In NBA.com's preseason GM Survey, GMs picked LeBron for MVP (30%) with Giannis an also-ran; Giannis won it.`,
  '2018:surprises': `LeBron James signed with the Lakers, and they still missed the playoffs. Anthony Davis then asked New Orleans for a trade and was sent to the Lakers that summer. Nobody expected anything from the post-Lob City Clippers, but Lou Williams and rookie Shai Gilgeous-Alexander won nearly 50 games, came back from 31 down against the Warriors and took them to six. In NBA.com's preseason GM Survey, 80% of GMs picked LeBron's Lakers as most improved; they went 37-45 and missed the playoffs.`,
  '2019:contenders': `Kawhi Leonard and Paul George made the Clippers instant title favorites in what was supposed to be a Battle of L.A., and everyone expected a Lakers-Clippers conference finals in the bubble. The Clippers blew a 3-1 lead to Denver and the Lakers won LeBron's fourth title. In NBA.com's preseason GM Survey, GMs picked the Clippers (48%) and Bucks (37%); the Lakers, a 7% pick, won the title.`,
  '2019:draft-drama': `New Orleans took Zion Williamson first, a pick that sparked real optimism before injuries took over, and Memphis took Ja Morant second, who was a near-unanimous Rookie of the Year. In NBA.com's preseason GM Survey, GMs picked Zion for Rookie of the Year (70%); Ja Morant won it.`,
  '2019:mvp-race': `The Bucks had the league's best record and Giannis Antetokounmpo won a second straight MVP over LeBron James and scoring champion James Harden, adding Defensive Player of the Year. Milwaukee then lost to Miami in the second round. In NBA.com's preseason GM Survey, GMs picked Giannis to repeat as MVP (54%), and he did.`,
  '2019:surprises': `Miami's signing of Jimmy Butler was called one of the worst of the summer. In the bubble, the Heat beat the top-seeded Bucks and Boston and reached the Finals. Golden State, with Durant gone and Curry and Thompson hurt, fell from the Finals to 15-50 in its first season at Chase Center. The Clippers, title favorites with Kawhi and George, blew a 3-1 lead to Denver in the bubble, maybe the worst collapse in NBA history. In NBA.com's preseason GM Survey, GMs ranked Miami seventh in the East; the Heat made the Finals.`,

  // ── 2020s ───────────────────────────────────────────────────────
  '2020:contenders': `Brooklyn added Harden to Durant and Irving and became the East favorite, Kawhi tore his ACL in a wide-open West, and Milwaukee, with newly acquired Jrue Holiday, beat Phoenix for its first title in 50 years. In 2021 Chris Paul's Suns beat the Lakers, Denver and the Clippers to reach their first Finals since 1993, while top-seeded Utah, with the league's best offense, lost to the Clippers in the second round. In NBA.com's preseason GM Survey, 81% of GMs picked the Lakers to repeat; Phoenix beat them in round one and the Bucks, their East pick, won it.`,
  '2020:draft-drama': `Burned by past picks, Minnesota shopped the No. 1 pick before taking Anthony Edwards, and people said the Wolves had landed another dud. Charlotte took LaMelo Ball third, and he was Rookie of the Year. In NBA.com's preseason GM Survey, GMs picked LaMelo Ball for Rookie of the Year (39%), and he won it.`,
  '2020:mvp-race': `Nikola Jokic, a 41st pick, won MVP in a landslide for a Denver team missing Jamal Murray, and won again the next year. In NBA.com's preseason GM Survey, GMs picked Giannis for MVP (32%) and had Jokic sixth (4%); Jokic won it.`,
  '2020:surprises': `Atlanta, which fired Lloyd Pierce at 14-20, rode Trae Young all the way to the conference finals. In NBA.com's preseason GM Survey, GMs ranked Phoenix eighth in the West; the Suns made the Finals, and Utah, ranked sixth, had the best record.`,
  '2021:contenders': `Phoenix dominated the season and was the favorite to get back to the Finals. Down 2-0, Luka Doncic's Mavericks blew them out in Game 7. Golden State, two years removed from 15-50, won 53 games and beat Boston for its fourth title in eight years, with Curry as Finals MVP. Chicago went all in on Vucevic and DeRozan and won 46, but Milwaukee beat them in five. In NBA.com's preseason GM Survey, GMs picked Brooklyn (72%) and had the Warriors fifth in the West; the Nets were swept in round one and Golden State won.`,
  '2021:draft-drama': `Detroit took Cade Cunningham first as expected, and Jalen Suggs, seen as a top-four pick, went fifth. Toronto's fourth pick, Scottie Barnes, edged Cleveland's third pick, Evan Mobley, for Rookie of the Year. In NBA.com's preseason GM Survey, GMs split between Jalen Green and Cade Cunningham for Rookie of the Year; Scottie Barnes won it.`,
  '2021:mvp-race': `Joel Embiid led the league at 30.6 points, but Nikola Jokić, at 27.1 points, 13.8 rebounds and 7.9 assists, won a second straight MVP over Embiid and Giannis Antetokounmpo. In NBA.com's preseason GM Survey, GMs picked Durant (37%) and Luka (33%) for MVP and gave Jokic no votes; Jokic won it.`,
  '2021:surprises': `At 26-25, Boston looked like a bottom-feeder and people asked whether Jaylen Brown would have to be traded. Brown tweeted that the energy was about to shift, and Boston made its first Finals in 12 years. Dallas, written off after trading Porzingis, demolished the top-seeded Suns in Game 7. Brooklyn's big three, which had promised dominance, fell apart: Harden was traded to Philadelphia in February, and Irving and Durant were gone a year later. In NBA.com's preseason GM Survey, GMs ranked the Celtics sixth in the East; they swept the favored Nets and made the Finals.`,
  '2022:contenders': `Cleveland's trade for Donovan Mitchell was seen as making it a contender. Boston's Tatum looked like he'd turned a corner, then the Celtics fell behind 3-0 to eighth-seeded Miami and lost Game 7 despite all the expectations. Denver finished first in the West, swept the Lakers and beat Miami 4-1 for its first title, with Jokic as Finals MVP. New owner Mat Ishbia's Suns traded for Kevin Durant, but finished only fourth in the West. In NBA.com's preseason GM Survey, GMs picked Milwaukee (43%) and gave Denver no title votes; the Nuggets won it and the Bucks lost in round one to Miami.`,
  '2022:draft-drama': `Jabari Smith Jr. was the long-expected No. 1 until draft day, when the reporting flipped to Duke's Paolo Banchero. Smith went third, and Banchero was Rookie of the Year. Orlando built a young, defensive core around him that was a 47-win playoff team two years later. In NBA.com's preseason GM Survey, GMs picked Paolo Banchero for Rookie of the Year (79%), and he won it.`,
  '2022:mvp-race': `Joel Embiid finally won MVP, leading the league at 33.1 points for a 54-win 76ers team, after years of second-round exits. Boston beat them in seven in the second round again. In NBA.com's preseason GM Survey, GMs picked Luka for MVP (48%) and Embiid third (14%); Embiid won it.`,
  '2022:surprises': `Miami barely made it as an eighth seed, then beat the 58-win, top-seeded Bucks 4-1 after Giannis got hurt in Game 1, then the Knicks and Boston to reach the Finals, where nobody outside Miami gave them a chance. Milwaukee fired Mike Budenholzer. The Knicks beat Mitchell's higher-seeded Cavs 4-1, and the Lakers went from the play-in to the conference finals. Off the court, Ja Morant was suspended for showing a gun on Instagram Live, and Draymond Green punched teammate Jordan Poole. Sacramento ended the longest playoff drought in league history at 16 seasons, winning 48 games behind Fox and Sabonis, before Curry's 50 in Game 7 knocked them out.`,
  '2023:contenders': `Boston was the only 60-win team and won the title through an East full of injured rivals, including a Bucks team that had traded Jrue Holiday for Damian Lillard and fired its coach at 30-13. The young Thunder topped the West far faster than anyone expected, and Dallas exposed their youth in the second round. Cleveland came back from 18 down in Game 7 against Orlando to win its first series since 2018. In NBA.com's preseason GM Survey, GMs split between Boston and Denver (33% each); Boston won the title, over a Dallas team ranked ninth in the West.`,
  '2023:draft-drama': `Behind Wembanyama, the debate was whether Charlotte would take Brandon Miller or Scoot Henderson at No. 2. The Hornets took Miller, seen as the better fit and shooter; he finished third for Rookie of the Year, while Henderson ranks 40th in the class in win shares. The Spurs won the lottery with 14% odds for Victor Wembanyama, a prospect called a unicorn, and people said their luck had struck again. In NBA.com's preseason GM Survey, GMs picked Wembanyama for Rookie of the Year (50%), and he won it unanimously.`,
  '2023:mvp-race': `Nikola Jokic won his third MVP for a 57-win Nuggets team, which then lost a seven-game series to Minnesota. In NBA.com's preseason GM Survey, GMs picked Jokic for MVP (43%), and he won it.`,
  '2023:surprises': `Dallas's gamble on Kyrie Irving took it to the Finals. Minnesota, once a laughing stock, knocked out the champion Nuggets with a Game 7 comeback from 20 down. Indiana, a 47-win sixth seed, reached the conference finals, and OKC took the top of the West years ahead of schedule. Detroit, meant to grow under new coach Monty Williams, lost an NBA-record 28 straight and finished 14-68. In NBA.com's preseason GM Survey, GMs ranked OKC tenth in the West; the Thunder finished first.`,
  '2024:contenders': `OKC won 68 games and was supposed to steamroll the playoffs. Denver nearly pulled the upset in seven, and Cleveland, 64-18 with the East's top seed, lost to Indiana in five. The Thunder beat the Pacers in seven, after Tyrese Haliburton tore his Achilles early in Game 7, and talk turned to a dynasty. At midseason the expected Finals had been the Thunder against defending champion Boston, which looked unbeatable; the Knicks knocked the Celtics out in the second round. Milwaukee recovered from a bad start but lost to Indiana in five, Golden State faded, added Dennis Schroder and still beat second-seeded Houston in seven, and Ja Morant's Grizzlies, near the top of the West in December, were swept by OKC. In NBA.com's preseason GM Survey, 83% of GMs picked Boston to repeat; OKC won it, and Indiana, ranked seventh in the East, took the Thunder to seven.`,
  '2024:draft-drama': `Brooklyn traded Mikal Bridges to the Knicks for four unprotected first-rounders and a swap, giving the Nets a league-high 15 first-round picks through 2031. Washington took French center Alex Sarr second and went 18-64 the next season. San Antonio drafted Stephon Castle to play next to Victor Wembanyama and Chris Paul, and Castle was a near-unanimous Rookie of the Year, though the Spurs missed the play-in. In NBA.com's preseason GM Survey, GMs picked Reed Sheppard for Rookie of the Year (50%); Stephon Castle won it.`,
  '2024:mvp-race': `Shai Gilgeous-Alexander swept MVP, Finals MVP and the scoring title for a 68-win team, despite the constant free-throw narrative. In NBA.com's preseason GM Survey, GMs picked SGA for MVP (40%), and he won it.`,
  '2024:surprises': `Dallas secretly traded Luka Doncic to the Lakers, a deal nobody saw coming. Indiana, an afterthought after a slow start, beat the 64-win Cavs and the Knicks behind Haliburton's game winners and took the heavily favored Thunder to Game 7. New York, in its first conference finals in 25 years, fired Tom Thibodeau anyway, and Denver fired Michael Malone with three games left. Detroit tripled its win total to make the playoffs a year after winning 14 games, and Philadelphia signed Paul George to win around Embiid and went 24-58. The Durant-Booker-Beal Suns went 36-46 and missed the playoffs, then traded Durant and waived Beal, and Sacramento fired Mike Brown and traded De'Aaron Fox. Some midseason verdicts missed: Minnesota, written off after the Towns trade, made the conference finals again; the Kawhi-less Clippers won 50; the Lakers, expected back in the play-in, finished third after landing Doncic; and Houston, called better on paper than in reality, finished second. New Orleans sank to 21-61 with Zion Williamson hurt again, Orlando lost Paolo Banchero and Franz Wagner to torn obliques and still made the playoffs, and Miami, amid Jimmy Butler trade rumors, got in through the play-in and was swept by Cleveland. In NBA.com's preseason GM Survey, GMs ranked Philadelphia third in the East after the Paul George signing; the 76ers went 24-58, while fourth-ranked Cleveland won 64.`,
  '2025:contenders': `Cleveland, adding Lonzo Ball, started 10-5 and was seen as a top-seed contender in the East again, and Detroit led the conference at 27-9 in January. Houston traded its young core for Kevin Durant, and the Lakers, with Doncic and LeBron, won 53 games before Oklahoma City swept them. The Knicks, who lost four straight in early January, were the ones who won it all, beating San Antonio 4-1 in the Finals behind Jalen Brunson's 45-point clincher to end a 53-year drought. In NBA.com's preseason GM Survey, GMs picked OKC to repeat (80%); the Spurs beat the Thunder in the West finals and the Knicks won the title.`,
  '2025:draft-drama': `Utah, a league-worst 17-65 after openly tanking, took Rutgers forward Ace Bailey fifth, a scorer once projected as a top-three pick. In NBA.com's preseason GM Survey, 97% of GMs picked Cooper Flagg for Rookie of the Year; he won it, but Kon Knueppel, who got no votes, nearly caught him.`,
  '2025:surprises': `Boston led Philadelphia 3-1 in the first round and lost three straight, and talk turned to whether the Brown-Tatum pairing had run its course. Chicago's young team opened 6-1, its best start since 1996-97, then lost five straight. Charlotte's young team ended Oklahoma City's 24-game streak against the East and climbed above .500, and Atlanta traded Trae Young, the face of the franchise, to Washington in January. Milwaukee waived the injured Damian Lillard and was projected at around 40 wins, while the post-Ujiri Raptors climbed to fifth in the East. Portland brought back Damian Lillard, out for the year with a torn Achilles, then lost coach Chauncey Billups to leave amid an NBA gambling probe and was still near .500 in February. In NBA.com's preseason GM Survey, GMs ranked the Spurs ninth in the West and Boston eighth in the East; the Spurs won 62 and made the Finals, Boston won 56 and Detroit 60.`,
  '2025:mvp-race': `In NBA.com's preseason GM Survey, GMs picked Jokic for a fourth MVP (67%) and SGA third (8%); SGA won it again.`,
  '2026:contenders': `In the preseason, the 76ers with LeBron at point guard were the team to watch if they stayed healthy, Indiana was expected back near the top of the East, Miami with Giannis looked like a fringe contender, and in the West, San Antonio was seen as the team in the way of OKC and Minnesota. The season is still being played.`,
  '2026:draft-drama': `Washington's No. 1 pick, AJ, came into a roster with Trae Young and Anthony Davis, and the preseason read was that he wouldn't have to be rushed into a high-usage role. The season is still being played.`,
};
